<?php
declare(strict_types=1);
namespace App\Services;
use PDO;
final class AccountLifecycle {public function __construct(private PDO $db){}
 public function requestCancel(int $user):void{$s=$this->db->prepare("UPDATE users SET cancellation_requested_at=COALESCE(cancellation_requested_at,NOW()) WHERE id=:u AND cancelled_at IS NULL");$s->execute(['u'=>$user]);$q=$this->db->prepare("UPDATE subscriptions SET status='cancelled',cancel_requested_at=NOW(),cancellation_due_at=DATE_ADD(NOW(),INTERVAL 10 DAY) WHERE user_id=:u AND status IN ('active','pending','past_due')");$q->execute(['u'=>$user]);$this->notification($user,'cancel_requested','Cancelamento solicitado','Sua conta será cancelada em até 10 dias. Não serão emitidas novas cobranças.');}
 public function closeDue():void{$rows=$this->db->query("SELECT id FROM users WHERE cancellation_requested_at IS NOT NULL AND cancelled_at IS NULL AND cancellation_requested_at<=DATE_SUB(NOW(),INTERVAL 10 DAY)")->fetchAll();foreach($rows as $r)$this->close((int)$r['id'],'cancelled');}
 public function closeSingleUse():void{$rows=$this->db->query("SELECT DISTINCT s.user_id FROM subscriptions s WHERE s.plan_id=(SELECT id FROM plans WHERE code='single') AND s.status='active' AND NOT EXISTS(SELECT 1 FROM campaigns c WHERE c.user_id=s.user_id AND c.status IN('draft','queued','running','paused'))")->fetchAll();foreach($rows as $r)$this->close((int)$r['user_id'],'single_use_complete');}
 private function close(int $user,string $type):void{$this->db->beginTransaction();try{$paths=$this->db->prepare('SELECT ci.storage_path FROM campaign_images ci JOIN campaigns c ON c.id=ci.campaign_id WHERE c.user_id=:u');$paths->execute(['u'=>$user]);$files=$paths->fetchAll();$this->db->prepare("UPDATE users SET status='suspended',cancelled_at=NOW(),retained_until=DATE_ADD(CURDATE(),INTERVAL 7 YEAR) WHERE id=:u")->execute(['u'=>$user]);$this->db->prepare("UPDATE subscriptions SET status='cancelled',cancelled_at=NOW() WHERE user_id=:u AND status<>'cancelled'")->execute(['u'=>$user]);$this->db->prepare("DELETE ci FROM campaign_images ci JOIN campaigns c ON c.id=ci.campaign_id WHERE c.user_id=:u")->execute(['u'=>$user]);$this->db->prepare('DELETE FROM campaigns WHERE user_id=:u')->execute(['u'=>$user]);$this->notification($user,$type,'Conta encerrada','Sua conta foi encerrada. Não haverá novas cobranças ou notificações.');$this->db->commit();foreach($files as $f){$p=$f['storage_path'];if(is_file($p))unlink($p);}}catch(\Throwable $e){$this->db->rollBack();throw$e;}}
 public function purgeExpired():void{$s=$this->db->query('SELECT id FROM users WHERE retained_until<CURDATE()');foreach($s->fetchAll() as $u){$this->db->prepare('DELETE FROM users WHERE id=:id')->execute(['id'=>$u['id']]);}}
 public function notifyUpcoming():void{$s=$this->db->query("SELECT f.user_id,f.amount_cents,f.payment_url FROM financial_transactions f JOIN subscriptions s ON s.id=f.subscription_id WHERE f.status='pending' AND s.payment_method IN('pix','boleto') AND DATE(f.due_at)=DATE_ADD(CURDATE(),INTERVAL 10 DAY)");foreach($s->fetchAll() as $f)$this->notification((int)$f['user_id'],'payment_due','Pagamento próximo do vencimento','Seu pagamento de R$ '.number_format($f['amount_cents']/100,2,',','.').' vence em 10 dias. Pague em: '.$f['payment_url']);}
 private function notification(int $u,string $type,string $title,string $body):void{$s=$this->db->prepare('INSERT INTO user_notifications(user_id,type,title,body) VALUES(:u,:t,:title,:body)');$s->execute(['u'=>$u,'t'=>$type,'title'=>$title,'body'=>$body]);}
}
